// Shared by the editor preview and the server. HTML from authors is always escaped.
export function formatArticleText(value = '') {
  return String(value)
    .replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]))
    .split(/(\n\s*\n)/)
    .map(block => block
      .replace(/\*\*(\S(?:[\s\S]*?\S)?)\*\*/g, '<strong>$1</strong>')
      .replace(/(?<![\p{L}\p{N}_])_(\S(?:[^_]*?\S)?)_(?![\p{L}\p{N}_])/gu, '<em>$1</em>'))
    .join('');
}

export function articlePlainText(value = '') {
  // Strip only the tags generated by our formatter, before decoding escaped text.
  return formatArticleText(value).replace(/<\/?(?:strong|em)>/g, '')
    .replace(/&(?:amp|lt|gt|quot|#39);/g, entity => ({ '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'" }[entity]));
}
